import { useNotification } from '@/contexts/notification/NotificationProvider';

interface NotificationOptions {
  message: string | string[];
  options:
    | {
        autoClose?: boolean | undefined;
        autoCloseTime?: number | undefined;
      }
    | undefined;
}

const Notification = () => {
  const { invoke, translateFunction } = useNotification();

  const info = (
    message: NotificationOptions['message'],
    options?: NotificationOptions['options'],
  ) => {
    // const { autoClose = true, autoCloseTime } = options || {};
    invoke(
      'info',
      Array.isArray(message)
        ? message[0]
        : (translateFunction ? translateFunction(message) : message) || '',
      { autoClose: options?.autoClose ?? true, autoCloseTime: options?.autoCloseTime ?? 3000 },
    );
  };

  const error = (
    message: NotificationOptions['message'],
    options?: NotificationOptions['options'],
  ) => {
    invoke(
      'error',
      Array.isArray(message)
        ? message[0]
        : (translateFunction ? translateFunction(message) : message) || '',
      { autoClose: options?.autoClose ?? true, autoCloseTime: options?.autoCloseTime ?? 3000 },
    );
  };

  const success = (
    message: NotificationOptions['message'],
    options?: NotificationOptions['options'],
  ) => {
    invoke(
      'success',
      Array.isArray(message)
        ? message[0]
        : (translateFunction ? translateFunction(message) : message) || '',
      { autoClose: options?.autoClose ?? true, autoCloseTime: options?.autoCloseTime ?? 3000 },
    );
  };

  const warn = (
    message: NotificationOptions['message'],
    options?: NotificationOptions['options'],
  ) => {
    invoke(
      'warn',
      Array.isArray(message)
        ? message[0]
        : (translateFunction ? translateFunction(message) : message) || '',
      { autoClose: options?.autoClose ?? true, autoCloseTime: options?.autoCloseTime ?? 3000 },
    );
  };

  return { info, error, success, warn };
};

export default Notification;

import React, {
  createContext,
  useContext,
  useState,
  ReactNode,
  useRef,
  useMemo,
  useCallback,
} from 'react';
import NotificationContainer from './NotificationContainer';

const defaultNotificationContext: INotificationContext = {
  invoke: () => {},
  translateFunction: () => {},
};

const NotificationContext = createContext<INotificationContext>(defaultNotificationContext);

export const useNotification = () => {
  const context = useContext(NotificationContext);
  if (!context) {
    throw new Error('useNotification must be used within a NotificationProvider');
  }
  return context;
};

interface INotification {
  children: ReactNode;
  newestTop?: boolean;
  closeIcon?: boolean;
  translateFunction?: (e: string | string[]) => void;
  theme?: 'colored' | 'default' | 'lined';
  mode?: 'light' | 'dark';
  containerClassName?: string;
  notificationClassName?: string;
  closeButtonClassName?: string;
  progressBarClassName?: string;
  animationMode?: 'bounce' | 'slide' | 'flip' | false;
  position?: 'top-right' | 'bottom-right' | 'top-left' | 'bottom-left';
}

interface INotificationContext {
  invoke: (
    type: string,
    message: string,
    options: { autoClose?: boolean; autoCloseTime?: number; icon?: ReactNode },
  ) => void;
  translateFunction?: (e: string | string[]) => void;
}

export const NotificationProvider: React.FC<INotification> = ({
  children,
  newestTop,
  closeIcon,
  translateFunction,
  theme,
  mode = 'light',
  containerClassName,
  notificationClassName,
  closeButtonClassName,
  progressBarClassName,
  animationMode = 'bounce' as 'flip' | 'bounce' | 'slide' | null | undefined,
  position = 'top-right',
}) => {
  const [notifications, setNotifications] = useState<
    {
      id: number;
      type: string;
      message: string;
      icon?: ReactNode;
      timeoutId?: NodeJS.Timeout;
      exiting?: boolean;
    }[]
  >([]);
  const [localAutoClose, setLocalAutoClose] = useState<{
    state: boolean | undefined;
    time: number | undefined;
  }>();
  const notificationIdRef = useRef(0);

  const invoke = useCallback(
    (
      type: string,
      message: string,
      options: { autoClose?: boolean; autoCloseTime?: number; icon?: ReactNode },
    ) => {
      setLocalAutoClose({ state: options.autoClose, time: options.autoCloseTime });
      const id = notificationIdRef.current++;
      const newNotification = {
        id,
        type,
        message,
        icon: options.icon,
        closeIcon,
        autoClose: options.autoClose,
        autoCloseTime: options.autoCloseTime,
      };

      setNotifications((prev) => [...prev, newNotification]);

      if (options.autoClose) {
        const timeoutId = setTimeout(() => {
          setNotifications((prev) =>
            prev.map((notification) =>
              notification.id === id ? { ...notification, exiting: true } : notification,
            ),
          );
          setTimeout(() => {
            setNotifications((prev) => prev.filter((notification) => notification.id !== id));
          }, 200); // Animasyon için bekleme süresi
        }, options.autoCloseTime ?? 3000);

        setNotifications((prev) =>
          prev.map((notification) =>
            notification.id === id ? { ...notification, timeoutId } : notification,
          ),
        );
      }
    },
    [closeIcon],
  );

  const clearNotification = (id: number) => {
    setNotifications((prev) => {
      const notification = prev.find((e) => e.id === id);
      if (notification && notification.timeoutId) {
        clearTimeout(notification.timeoutId);
      }
      return prev.map((notification) =>
        notification.id === id
          ? { ...notification, exiting: true, autoClose: false }
          : notification,
      );
    });
    setTimeout(() => {
      setNotifications((prev) => prev.filter((notification) => notification.id !== id));
    }, 200); // Animasyon için bekleme süresi
  };

  const values = useMemo(
    () => ({
      invoke,
      translateFunction,
    }),
    [invoke, translateFunction],
  );

  return (
    <NotificationContext.Provider value={values}>
      {children}
      <NotificationContainer
        notifications={notifications}
        onRemove={clearNotification}
        newestTop={newestTop}
        theme={theme}
        mode={mode}
        autoClose={localAutoClose?.state}
        autoCloseTime={localAutoClose?.time}
        containerClassName={containerClassName}
        notificationClassName={notificationClassName}
        closeButtonClassName={closeButtonClassName}
        progressBarClassName={progressBarClassName}
        animationMode={animationMode || undefined}
        position={position}
      />
    </NotificationContext.Provider>
  );
};

