        theme: 'colored',
        type: 'warn',
        className: 'bg-warning!',
      },
    ],
  },
);

const NotificationContainer: React.FC<{
  notifications: {
    id: number;
    type: string;
    message: string;
    icon?: ReactNode;
    closeIcon?: boolean;
    autoClose?: boolean;
    autoCloseTime?: number;
    exiting?: boolean;
  }[];
  onRemove: (id: number) => void;
  newestTop?: boolean;
  theme?: 'colored' | 'default' | 'lined';
  mode?: 'light' | 'dark';
  autoCloseTime?: number | undefined | boolean;
  autoClose?: boolean;
  containerClassName?: string;
  notificationClassName?: string;
  closeButtonClassName?: string;
  progressBarClassName?: string;
  animationMode?: 'bounce' | 'slide' | 'flip' | null;
  position?: 'top-right' | 'bottom-right' | 'top-left' | 'bottom-left';
}> = ({
  notifications,
  onRemove,
  newestTop,
  theme = 'colored',
  mode = 'light',
  autoCloseTime,
  containerClassName,
  notificationClassName,
  closeButtonClassName,
  progressBarClassName,
  animationMode = 'bounce',
  position = 'top-right',
}) => {
  const [manualExitIds, setManualExitIds] = useState<Set<number>>(new Set());
  const ordered = newestTop ? [...notifications].reverse() : notifications;
  const visibleNotifications = ordered.map((n) =>
    manualExitIds.has(n.id) ? { ...n, exiting: true } : n,
  );

  const handleRemove = (id: number) => {
    setManualExitIds((prev) => new Set(prev).add(id));
    setTimeout(() => {
      onRemove(id);
      setManualExitIds((prev) => {
        const next = new Set(prev);
        next.delete(id);
        return next;
      });
    }, 100); // Animasyon için bekleme süresi
  };

  return (
    <div
      className={cn(
        containerVariants({ position, isHaveNotifications: Boolean(notifications?.length) }),
        containerClassName,
      )}
    >
      {visibleNotifications.map((notification) => (
        <div
          key={notification.id}
          className={cn(
            notificationVariants({
              type: notification.type as 'info' | 'error' | 'success' | 'warn',
              exiting: notification.exiting,
              theme,
              mode,
              animationMode,
              position,
            }),
            notificationClassName,
          )}
          onClick={() => handleRemove(notification.id)}
          onAnimationEnd={(e) => {
            if (e.animationName === 'bounceOutRight') {
              onRemove(notification.id);
            }
          }}
        >
          {notification.icon}
          <span>{notification.message}</span>
          {notification.closeIcon && (
            <Button
              size="icon"
              className={cn(
                'absolute right-2.5 top-2.5 m-0 size-fit max-h-fit min-h-fit min-w-fit max-w-fit rounded-full bg-black/30 p-px hover:bg-black/50',
                closeButtonClassName,
              )}
              onClick={() => handleRemove(notification.id)}
            >
              <XIcon className="size-4" />
            </Button>
          )}
          {notification.autoClose && (
            <div
              className={cn(
                notificationProgressBar({
                  theme,
                  type: notification.type as 'info' | 'error' | 'success' | 'warn',
                }),
                progressBarClassName,
              )}
              style={{ animationDuration: `${autoCloseTime}ms` }}
            />
          )}
        </div>
      ))}
    </div>
  );
};

export default NotificationContainer;
